  ('medjumbe-island-mozambique', '06A', 'Medjumbe Island', 'Mozambique', 'Twelve villas, one tiny island, and reef walls plunging', 'future', 'verified', 'venice', 'Mozambique & Coast', '{"romance","diveglobal"}', '{}', '{"premier","ultra"}', null, null, '{"key_facts":["BOOKING HOLD: private island in the Quirimbas / Cabo Delgado, US Level 4 Do Not Travel (ISIS-linked insurgency; islands occupied; kidnapping; Palma 2021). CONTENT-ONLY, no Book path, no waiver even for this ultra-luxury island","~1 km x 500 m private island; home to Anantara Medjumbe (12 beach pool villas, formerly Rani flagship), ''ultimate honeymooners'' getaway''","Reef drop-offs up to 400 m + coral caves (Napoleon wrasse; humpback whales in season) - world-class wall diving (HELD)","Signature romance (''Night Under the Stars'' castaway dining on Quissanga sandbank) (HELD)","MALARIA HIGH; cyclone Dec-Apr; nearest care Pemba is itself L4; no assured evacuation from a remote island","Live redirect: Bazaruto Archipelago / southern Mozambique (bookable, far from Cabo Delgado)"],"safety":{"zone":"Cabo Delgado Province","emergency":"police 119 (also 112); INEM ambulance 117 (non-functional in conflict zone)","hospital":"Pemba - itself L4; no assured evacuation","advisory_level":"L4","malaria":"HIGH","yellow_fever":"required only if arriving from an endemic country","cyclone":"Dec-Apr","activity_note":"SECURITY-DOMINANT: ISIS-linked insurgency + kidnapping is the disqualifying hazard - Quirimbas islands occupied, no assured evac from a remote island. World-class 400m wall diving + HIGH malaria are secondary and moot while held. CONTENT-ONLY, no waiver.","booking_hold":true,"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel to Cabo Delgado Province, except for Palma town and the area around Pemba and Afungi."},{"form":"against all travel","text":"advises against all travel to the districts of Memba and Eráti in Nampula Province."},{"form":"against all travel","text":"advises against all travel to the districts of Mecula and Marrupo in Niassa Province."},{"form":"against all travel","text":"advises against all travel to Cabo Delgado, except Palma town and the area around Pemba and Afungi, due to attacks by groups with links to Islamist extremism and clashes between insurgents, armed vigilante groups and Mozambican security forces."},{"form":"against all travel","text":"advises against all travel to the districts of Memba and Eráti in Nampula Province due to attacks by groups with links to Islamist extremism."},{"form":"against all travel","text":"advise against all travel to the Mecula and Marrupo districts of Niassa Province."},{"form":"against all but essential travel","text":"advises against all but essential travel to Palma town and the area around Pemba and Afungi."}],"url":"https://www.gov.uk/foreign-travel-advice/mozambique","read":"2026-08-19","page_updated":"2026-07-09T15:47:45+01:00"}},"timing":{"booking_status":"HELD - no live demand while Level 4 stands","latent_peak":"May-Nov (dry, best diving; humpbacks ~Jul-Oct) - IF cleared","latent_green_cyclone":"Dec-Apr (cyclone season)","reverify_trigger":"check Cabo Delgado advisory every publish cycle; booking stays suppressed until State Dept + UK FCDO stand down","redirect":"live honeymoon/island demand -> Bazaruto Archipelago (southern Mozambique) / Seychelles / Zanzibar / Maldives"},"jewels":[{"name":"Anantara Medjumbe Island Resort","si_tag":"romance","status":"held","tier":"ultra","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"si":"romance","when":"HELD","commission":"none (advisory hold)"},{"name":"''Night Under the Stars'' / Quissanga sandbank","si_tag":"romance","status":"held","tier":"ultra","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"si":"romance","when":"HELD","commission":"none (advisory hold)"},{"name":"Medjumbe reef-wall dives (400m + coral caves)","si_tag":"diveglobal","status":"held","tier":