ao Island This advice is due to terrorist activity and clashes between the military and insurgent groups in south Philippines."}],"url":"https://www.gov.uk/foreign-travel-advice/philippines","read":"2026-08-19","page_updated":"2026-07-15T09:55:25+01:00"}},"timing":{"peak":"mid-Mar to mid-Jun (park-set season, liveaboard-only)","shoulder":"none","green":"closed the rest of the year","booking_lead":"historically many months out for the marquee boats; NOT bookable through TWW while held content-only","off_season_specials":"none - closed outside the window","event_peaks":"none","campaign_start":"none while held; re-evaluate if the advisory-boundary question is resolved"},"jewels":[{"name":"Shark Airport","si_tag":"liveaboard","status":"live","tier":"premier","hook":"grey reef sharks on nearly every dive","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"grey reef sharks on nearly every dive","when":"mid-Mar to mid-Jun","commission":"held - fleet-direct (Aggressor) when resolved"},{"name":"Delsan Wreck","si_tag":"liveaboard","status":"live","tier":"premier","hook":"wreck with pelagic action","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"wreck with pelagic action","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Malayan Wreck (North Atoll)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"north-atoll wreck and wall","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"north-atoll wreck and wall","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Black Rock","si_tag":"liveaboard","status":"live","tier":"premier","hook":"atoll wall dive","bookable_category":"liveaboard berth (held)","source":"https://philippinedives.com/dive-guide/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"atoll wall dive","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Southwest Wall","si_tag":"liveaboard","status":"live","tier":"premier","hook":"steep atoll wall","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"steep atoll wall","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Jessie Beazley Reef","si_tag":"liveaboard","status":"live","tier":"premier","hook":"isolated reef north of the atolls, pelagics","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"isolated reef north of the atolls, pelagics","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Staghorn Point","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"staghorn-coral reef","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"staghorn-coral reef","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Ko-ok","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"reef dive","bookable_category":"liveaboard berth (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"reef dive","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Triggerfish City","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"reef with nesting triggerfish","bookable_category":"liveaboard berth (held)","source":"https://philippinedives.com/dive-guide/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"reef with nesting triggerfish","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"North Atoll wall circuit","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the northern atoll''s wall dives","bookable_category":"liveaboard week (held)","source":"https://philippinedives.com/dive-guide/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the northern atoll''s wall dives","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"South Atoll wall circuit","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the southern atoll''s wall dives","bookable_category":"liveaboard week (held)","source":"https://philippinedives.com/dive-guide/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the southern atoll''s wall dives","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Tubbataha liveaboard week (mid-Mar-mid-Jun)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"two-atoll + Jessie Beazley arc, park-season only","bookable_category":"liveaboard week (held)","source":"https://masterliveaboards.com/philippines/tubbataha-national-park/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"two-atoll + Jessie Beazley arc, park-season only","when":"mid-Mar to mid-Jun","commission":"held"},{"name":"Tubbataha Reefs UNESCO World Heritage marine park","si_tag":"globaladv","status":"future","tier":"premier","hook":"one of the planet''s recorded marine-biodiversity peaks; ranger-protected","bookable_category":"content / expedition (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"one of the planet''s recorded marine-biodiversity peaks; ranger-protected","when":"mid-Mar to mid-Jun","commission":"held"}],"faq":[{"q":"What is the current advisory for Tubbataha, and why is it not bookable here?","a":"The Philippines carries a U.S. State Department Level 2 - Exercise Increased Caution rating nationwide (reissued 8 May 2025, with a Kidnapping ''K'' indicator). The advisory also designates a Level 4 (Do Not Travel) zone - ''The Sulu Archipelago, including the southern Sulu Sea, due to crime, terrorism, civil unrest, and kidnapping.'' The UK FCDO (reissued 1 April 2026) advises against all travel to western and central Mindanao and the Sulu archipelago. Tubbataha sits in the Sulu Sea, administratively Cagayancillo, Palawan, roughly 150 km southeast of Puerto Princesa. The advisory names ''the southern Sulu Sea'' as Level 4 but never draws that zone''s boundary and does not mention Tubbataha; no park-authority, UNESCO or operator source resolves it either. Because the park''s position relative to the Level 4 zone could not be established from any source that draws the line, TravelWell holds this destination as content-only and does not offer it as bookable until the question is resolved with the park authority against the live advisory.","source":"State L4 wording confirmed via childabduction.state.gov mirror 2026-08-10; L2/K + FCDO 1 Apr 2026 supplied by Strategy Claude from a 2026-08-09 read of travel.state.gov + gov.uk/foreign-travel-advice/philippines","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"Care is remote and the sources disagree, so treat this as not verifiable as of 2026-08-10. Some operators cite a chamber at the city hospital in Puerto Princesa, Palawan, roughly 10-12 hours away by boat; one dive guide names Cebu City instead; and Master Liveaboards lists facilities at Batangas, Manila, Cebu and Subic reached by private air evacuation, without naming Puerto Princesa. No source confirms a 24-hour operational status. DAN membership and dive-accident insurance with air-evacuation cover are essential.","source":"tubbataha.ph + philippinedives.com + divehappy.com + masterliveaboards.com/faq/philippines (accessed 2026-08-10)","si_tag":"safety"},{"q":"When can I dive Tubbataha?","a":"Only in the mid-March to mid-June window, when park authorities open the season for the calmest weather; exact dates are set each year by the Tubbataha Management Office. It is liveaboard-only - no shore access and no night diving - with boats running from Puerto Princesa.","source":"dan.org/alert-diver/article/tubbataha + tubbataha.ph + masterliveaboards.com/philippines/tubbataha-national-park (accessed 2026-08-10)","si_tag":"planning"},{"q":"What will I see underwater?","a":"The park is recorded at hundreds of coral and fish species; grey reef sharks appear on nearly every dive, typically in groups, alongside whitetips and - depending on the day - hammerheads, thresher and whale sharks, mantas, and nesting hawksbill and green turtles.","source":"philippinedives.com/dive-guide/tubbataha + dan.org/alert-diver/article/tubbataha + masterliveaboards.com (accessed 2026-08-10)","si_tag":"liveaboard"},{"q":"Which sites define a Tubbataha week?","a":"Shark Airport for the grey-reef aggregation, the Delsan and Malayan wrecks, the walls at Black Rock, Southwest Wall and the North and South Atolls, Staghorn Point and Ko-ok, and the isolated Jessie Beazley Reef to the north.","source":"dan.org/alert-diver/article/tubbataha + philippinedives.com/dive-guide/tubbataha (accessed 2026-08-10)","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"The atoll walls and Jessie Beazley are current-swept blue-water dives suited to experienced divers; sheltered reef tops suit a wider range with a guide. Nitrox is standard on the liveaboards. Dive within your certification and the operator briefing.","source":"masterliveaboards.com/philippines/tubbataha-national-park (accessed 2026-08-10)","si_tag":"liveaboard"}],"seo":{"meta_title":"Tubbataha Reefs Diving, Philippines: Season & Safety","meta_description":"Tubbataha Reefs, a UNESCO Sulu Sea liveaboard reef - the mid-March to mid-June season, the atoll walls and sharks, operators, and why booking is currently held.","slug":"tubbataha-philippines","primary_keyword":"Tubbataha Reefs liveaboard diving","long_tail":["Tubbataha dive season","Shark Airport Tubbataha","Tubbataha liveaboard","Sulu Sea advisory","Jessie Beazley Reef"],"search_language":"en","local_keywords":["Tubbataha Reefs","Sulu Sea diving"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-10"},"booking":{"bin":"content_only_boundary_unresolved","level":"L2","booking_hold":true,"codes":["L2","L4-zone-unresolved"],"note":"HELD CONTENT-ONLY. Philippines is US State L2 nationwide, reissued 8 May 2025, Kidnapping ''K'' indicator. The advisory designates a LEVEL 4 (Do Not Travel) zone: ''The Sulu Archipelago, including the southern Sulu Sea, due to crime, terrorism, civil unrest, and kidnapping.'' Tubbataha sits in the Sulu Sea ~150km SE of Puerto Princesa (Cagayancillo, Palawan). NO source that draws the line - the advisory text, the Tubbataha Management Office, UNESCO, or the operators - states whether the park is inside or outside that L4 zone; the boundary could NOT be established and was NOT ruled from a map. Held booking_hold:true pending resolution with the park authority against the live advisory. FCDO (1 Apr 2026): against all travel to western/central Mindanao + the Sulu archipelago. CITATION: L4 wording confirmed verbatim 2026-08-10 via the identical-text childabduction.state.gov mirror (travel.state.gov 403''d); L2/K + FCDO wording supplied by Strategy Claude from a 2026-08-09 read of travel.state.gov + gov.uk/foreign-travel-advice/philippines."},"si_checklist_25":{"run_date":"2026-08-10","hits":3,"misses":19,"disregarded":3,"note":"Liveaboard-diving scope, held content-only; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"HELD - private full-boat Philippine Siren / Philippines Aggressor charter across both atolls + Jessie Beazley + Palawan/El Nido land stay","why_ultra":"would be the ultra pull once the advisory boundary is resolved; not offered while content-only","earning":"held Aggressor reseller line - not booked while held","virtuoso_value_add":"n/a while held","mor":"n/a while held","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-10","hero":{"query":"Tubbataha Reefs, Philippines"},"geo":{"lat":8.85,"lng":119.92}}'::jsonb, 10),
  ('upper-mekong-laos', '07A', 'The Upper Mekong, Laos', 'Laos', 'The Mekong''s quiet crown', 'live', 'verified', 'venice', 'Southeast Asia', '{"river","culture","deepdive","culinary","adventure","romance","senior"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Upper Mekong Huay Xai<->Luang Prabang on LOW-DRAFT boutique boats (Heritage Line Anouvong 4-day ~$1,939pp, Pandaw, Luang Say, Nagi of Mekong) - big VN/KH lines can''t run this reach","Luang Prabang - UNESCO World Heritage town (1995): gilded wats (Wat Xieng Thong), French-colonial streets, dawn Tak Bat alms","Pak Ou Caves - ~4,000 Buddha images in two river caverns; Pak Beng overnight; Golden Triangle at Huay Xai; Kuang Si Falls near LP","US L2 (crime+UXO, reissued 2024-11-21); Xaisomboun Province = L3 Reconsider (off every cruise route)","SAFETY-SPINE: UXO (Indochina War) - advisory NAMES Luang Prabang + Vientiane - stay on well-used paths, never touch unknown metal","Landlocked (SE Asia''s only); currency Lao kip (LAK), USD/THB accepted; medevac to Thailand for serious cases"],"safety":{"emergency":"191 police / 190 fire / 195 ambulance (Laos lines; rural response limited)","hospital":"Luang Prabang + Vientiane basic; serious cases medevac to Thailand (Udon Thani/Bangkok) - air-medevac insurance advised","advisory_level":"L2","malaria":"low in Luang Prabang/river corridor (mosquito precautions; dengue present)","yellow_fever":"not required unless from endemic country","activity_note":"UXO safety-spine - stay on well-used roads/tracks/paths, never touch unknown metal (advisory names Luang Prabang + Vientiane); Xaisomboun L3 excluded; Mekong fast + low-draft water-dependent stretches (life vest, follow crew); Tak Bat observed silently at distance; hot/humid; dengue; rural care limited","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Xaisomboun Province FCDO advises agains